acceptance.tests:
def check(parse_kv):
    assert parse_kv('a=1;b=two') == {'a': '1', 'b': 'two'}
    assert parse_kv(' a = 1=2 ; ; b = x ') == {'a': '1=2', 'b': 'x'}
    for bad in ('a', '=1', 'a=1;b'):
        try:
            parse_kv(bad)
        except ValueError:
            pass
        else:
            raise AssertionError(bad)
check(parse_kv)

def check(summarize_events):
    result = summarize_events(['INFO|api|started', 'ERROR|db|timeout', 'ERROR|db|retry', 'WARN|api|slow', '', 'DEBUG|cache|hit', 'malformed'])
    assert result['counts'] == {'INFO': 1, 'WARN': 1, 'ERROR': 2}
    assert result['components'] == {'api': 2, 'db': 2}
    empty = summarize_events(['', 'DEBUG|cache|hit', 'broken'])
    assert empty == {'counts': {'INFO': 0, 'WARN': 0, 'ERROR': 0}, 'components': {}}
check(summarize_events)
